// The service worker's source (docs/MOBILE.md §7), generated by vite.config.ts at build time; a pure
// function so a unit test can run it against fake caches.
//
// - The app shell (index.html, the hashed JS / CSS / worker chunks and the public files) is precached
//   on install, so the app starts fast and solo plays offline. The cache name is a hash of the file
//   list, so every deploy installs a new worker, which waits until the page asks it to take over
//   ("Update available — tap to reload").
// - Recorded sound files (`/music/*.mp3`, `/sfx/*.mp3`, docs/SOUND_FILES.md) are never precached:
//   music is several MB, and a player who never hears the boss music shouldn't download it on install.
//   Each one is cached the first time the game fetches it, in a cache that outlives deploys
//   (`tdt-media`); the URL carries the file's hash (`?v=`), so a new upload is fetched fresh and
//   replaces the old copy. Music streams from an <audio> element first (docs/ART.md §13), which asks
//   with byte ranges: a stored file answers them with 206s, as a stage video does; before the file is
//   stored, a range goes to the network as it is, so the music starts with its first bytes (the
//   decode's whole request, which comes once the element has the file, is the one kept).
// - The lobby stage's videos (`/stage/*.mp4`, `/stage/*.webm`, docs/ART.md §15) are media too: up to 1.2 MB each,
//   cached the first time the stage plays one, never on install. A video is stored whole: the first time a video
//   element asks for it, with a byte range as video elements do, the worker fetches the whole file without the range
//   (a 200 the cache can keep; a 206 can't be stored) and answers the range from it; every later range is answered
//   from the stored file with a 206 and its Content-Range. iPhones play a video only from proper range answers: a
//   whole 200 to a range request can stop it playing. Their posters and the empty clearing are small pictures shown
//   at once on the first screen, so they are part of the shell.
// - The match's 3D sheets (V-07d, docs/ART.md §15): the creeps' and the heroes' (`/assets/<kind>-match-<hash>.webp`
//   or `.png`, about 4 MB together) and, since V-08b build 4, the towers', Heart's and portals' pages
//   (`/assets/structures-match-<n>-<hash>.webp`, 7 MB since the turrets' eight headings) are not precached: an install
//   that fetched them would share a first visit's line with the very sheets its first match is waiting for (on Slow 4G
//   the four pages alone are about 40 s of it). Each is kept in this version's cache the first time a match asks for
//   it, so the next match, and solo offline, has it; a first visit's page loads them before the worker controls it, so
//   the page tells it which it has (`KEEP_SHEETS`) and the worker fetches each from the HTTP cache. A deploy's new
//   worker drops them with the old cache (their names carry their hash, so a new picture is a new file anyway).
// - The link-preview card (`/og-card.png`, docs/PRESS.md) is not precached either: only link
//   crawlers fetch it, so a player would download it on every deploy for nothing.
// - A page load gets index.html (the game), except another page of the shell (privacy.html), which
//   gets itself.
// - It only serves same-origin GET requests; the game server's WebSocket never goes through it.
// - A hosted build (`npm run build:embed`, docs/DEPLOY.md "Hosted builds") gets the same worker with its paths relative
//   to the worker's folder, which the host chooses (`hosted`): its caches are named after that folder (`tdt@<folder>:`)
//   and it answers only for files under it, since the host's origin serves other games too. The site's worker is
//   generated word for word as before.

/** Files in the shell that are not precached: recorded sound files and stage videos (cached on first play instead). */
export function isMediaPath(path: string): boolean {
  return /^\/(music|sfx)\//.test(path) || isStageVideo(path);
}

/**
 * A 3D match sheet (`/assets/<kind>-match-<hash>.webp|png`: a creep's, a hero's, or since V-08b build 4 a page of the
 * structures', `structures-match-<n>-<hash>.webp`), or the map plate's dusk or night (`/map/spire-dusk.webp`,
 * `-night-extra.webp`…; V-08a): not precached, kept in this version's cache the first time a match asks for it (`sheet`
 * in the worker). The afternoon's plate is not: it is precached.
 */
export function isOnDemandSheet(path: string): boolean {
  return /^\/assets\/[a-z]+-match-[\w-]+\.(webp|png)$/.test(path) || /^\/map\/[a-z]+-(dusk|night)(-extra)?\.webp$/.test(path);
}

/** A stage video: stored whole, and range requests answered from it (`video` in the worker). */
export function isStageVideo(path: string): boolean {
  return /^\/stage\/[^/]+\.(mp4|webm)$/.test(path);
}

/** Public files for link previews only; players never load them. */
export const PREVIEW_FILES: readonly string[] = ['/og-card.png'];

export const MEDIA_CACHE = 'tdt-media';

/** The site's worker, the hosted build's beside it. Both share the helpers (`HELPERS`), word for word. */
export function swSource(version: string, files: string[], hosted = false): string {
  const shell = files.filter((f) => !isMediaPath(f) && !isOnDemandSheet(f) && !PREVIEW_FILES.includes(f));
  if (hosted) return hostedSource(version, shell);
  return `// Generated by vite.config.ts at build time. Do not edit.
const CACHE = 'tdt-${version}';
const MEDIA = '${MEDIA_CACHE}';
const SHELL = ${JSON.stringify(shell)};

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(SHELL)));
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('tdt-') && k !== CACHE && k !== MEDIA).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

// The page asks a waiting worker to take over when the player taps "Update available", and tells it which match
// sheets it has loaded (a first visit's page is not the worker's yet): they are kept, fetched from the HTTP cache.
self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') self.skipWaiting();
  if (event.data && event.data.type === 'KEEP_SHEETS' && Array.isArray(event.data.urls)) {
    const urls = event.data.urls
      .filter((u) => typeof u === 'string')
      .map((u) => new URL(u, self.location.origin))
      .filter((u) => u.origin === self.location.origin && onDemand(u.pathname));
    event.waitUntil(
      caches.open(CACHE).then((cache) =>
        Promise.all(
          urls.map((u) =>
            cache
              .match(u.href, { ignoreSearch: true })
              .then((hit) => hit || fetch(u.href).then((res) => (res.ok && res.status === 200 ? cache.put(u.href, res) : undefined)))
              .catch(() => {}),
          ),
        ),
      ),
    );
  }
});

${HELPERS}${SITE_FETCH}`;
}

/**
 * A hosted build's worker (docs/DEPLOY.md "Hosted builds"): the same caching, with the shell's paths relative to the
 * worker's folder, the caches named after that folder, and only the upload's own files answered. The page in a hosted
 * build is index.html alone (the privacy page is the real game's).
 */
function hostedSource(version: string, shell: string[]): string {
  const relative = shell.map((f) => f.replace(/^\//, ''));
  return `// Generated by vite.config.ts at build time for a hosted build (docs/DEPLOY.md "Hosted builds"). Do not edit.
// The host chose where the upload lives, and its origin serves other games too: every path here is relative to this
// worker's folder (ROOT), the worker answers only for files under it, and its caches carry it, so another game on the
// host's origin, or another upload of this one, keeps its own.
const ROOT = new URL('./', self.location.href).pathname;
const PREFIX = 'tdt@' + ROOT + ':';
const CACHE = PREFIX + '${version}';
const MEDIA = PREFIX + 'media';
const SHELL = ${JSON.stringify(relative)};

// A URL's path as the site would have it ('/assets/x.js'), when it is a file of this upload; null otherwise.
function local(url) {
  if (url.origin !== self.location.origin || !url.pathname.startsWith(ROOT)) return null;
  return '/' + url.pathname.slice(ROOT.length);
}

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(SHELL)));
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith(PREFIX) && k !== CACHE && k !== MEDIA).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

// The page tells the worker which match sheets it has loaded (a first visit's page is not the worker's yet):
// they are kept, fetched from the HTTP cache. A host's upload has no update banner, so nothing asks it to skip waiting.
self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'KEEP_SHEETS' && Array.isArray(event.data.urls)) {
    const urls = event.data.urls
      .filter((u) => typeof u === 'string')
      .map((u) => new URL(u, self.location.href))
      .filter((u) => local(u) !== null && onDemand(local(u)));
    event.waitUntil(
      caches.open(CACHE).then((cache) =>
        Promise.all(
          urls.map((u) =>
            cache
              .match(u.href, { ignoreSearch: true })
              .then((hit) => hit || fetch(u.href).then((res) => (res.ok && res.status === 200 ? cache.put(u.href, res) : undefined)))
              .catch(() => {}),
          ),
        ),
      ),
    );
  }
});

${HELPERS}${HOSTED_FETCH}`;
}

/** The helpers both workers carry: which files are sheets, the media and sheet caches, byte ranges. */
const HELPERS = `// A 3D match sheet (a creep's, a hero's or a page of the structures'), or the map plate's dusk or night
// (isOnDemandSheet in swSource.ts).
function onDemand(path) {
  return /^\\/assets\\/[a-z]+-match-[\\w-]+\\.(webp|png)$/.test(path) || /^\\/map\\/[a-z]+-(dusk|night)(-extra)?\\.webp$/.test(path);
}

// Keeps a whole answer (200) in the media cache, dropping older uploads of the same file (another ?v=).
function keep(cache, href, url, res) {
  if (!res.ok || res.status !== 200) return;
  const copy = res.clone();
  cache
    .keys()
    .then((keys) => Promise.all(keys.filter((k) => new URL(k.url).pathname === url.pathname && k.url !== href).map((k) => cache.delete(k))))
    .then(() => cache.put(href, copy))
    .catch(() => {});
}

// A recorded sound file: from the media cache (a range, a music element's, answered from it), else the network as
// asked, a whole answer kept for next time.
function media(req, url) {
  return caches.open(MEDIA).then((cache) =>
    cache.match(req).then((hit) => {
      if (hit) return answer(req, hit);
      return fetch(req).then((res) => {
        keep(cache, req.url, url, res);
        return res;
      });
    }),
  );
}

// Which bytes a Range header asks for, of a file of \`size\` bytes (RFC 9110 §14): { start, end } (inclusive), 'none'
// when it asks for nothing the file has (416), or null when there is no single range to answer (the whole file).
function byteRange(header, size) {
  const m = /^bytes=(\\d*)-(\\d*)$/.exec((header || '').trim());
  if (!m || (m[1] === '' && m[2] === '')) return null;
  let start;
  let end;
  if (m[1] === '') {
    const suffix = Number(m[2]);
    if (suffix === 0) return 'none';
    start = Math.max(0, size - suffix);
    end = size - 1;
  } else {
    start = Number(m[1]);
    end = m[2] === '' ? size - 1 : Math.min(Number(m[2]), size - 1);
    if (m[2] !== '' && Number(m[2]) < start) return null;
  }
  if (start >= size || size === 0) return 'none';
  return { start, end };
}

// Answers a request from a whole stored file: the file itself, or the range it asks for (206, Content-Range).
function answer(req, whole) {
  const header = req.headers && req.headers.get('range');
  if (!header) return whole;
  return whole.blob().then((blob) => {
    const type = whole.headers.get('content-type') || blob.type || 'application/octet-stream';
    const r = byteRange(header, blob.size);
    if (r === null) {
      return new Response(blob, { status: 200, headers: { 'Content-Type': type, 'Content-Length': String(blob.size), 'Accept-Ranges': 'bytes' } });
    }
    if (r === 'none') return new Response(null, { status: 416, headers: { 'Content-Range': 'bytes */' + blob.size } });
    return new Response(blob.slice(r.start, r.end + 1, type), {
      status: 206,
      statusText: 'Partial Content',
      headers: {
        'Content-Type': type,
        'Content-Length': String(r.end - r.start + 1),
        'Content-Range': 'bytes ' + r.start + '-' + r.end + '/' + blob.size,
        'Accept-Ranges': 'bytes',
      },
    });
  });
}

// A stage video: stored whole on first play, every request (a range or not) answered from the stored file.
function video(req, url) {
  return caches.open(MEDIA).then((cache) =>
    cache.match(url.href).then((hit) => {
      if (hit) return answer(req, hit);
      // Without the Range header: the whole file, a 200 the cache can keep.
      return fetch(url.href, { credentials: 'same-origin' }).then((res) => {
        if (!res.ok || res.status !== 200) return res;
        keep(cache, url.href, url, res);
        return answer(req, res);
      });
    }),
  );
}

// A creep's or a hero's match sheet: from this version's cache, else the network, a whole answer kept for next time.
function sheet(req) {
  return caches.open(CACHE).then((cache) =>
    cache.match(req, { ignoreSearch: true }).then((hit) => {
      if (hit) return hit;
      return fetch(req).then((res) => {
        if (res.ok && res.status === 200) cache.put(req, res.clone()).catch(() => {});
        return res;
      });
    }),
  );
}

`;

/** The site's fetch handler. */
const SITE_FETCH = `self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  // Only this site's own files; never the game server.
  if (url.origin !== self.location.origin || url.pathname === '/sw.js') return;
  if (/^\\/stage\\/[^/]+\\.(mp4|webm)$/.test(url.pathname)) {
    event.respondWith(video(req, url));
    return;
  }
  if (/^\\/(music|sfx)\\//.test(url.pathname)) {
    event.respondWith(media(req, url));
    return;
  }
  if (onDemand(url.pathname)) {
    event.respondWith(sheet(req));
    return;
  }
  if (req.mode === 'navigate') {
    // App shell first (fast start, offline solo); the network if it is not cached yet. Another page of
    // the shell (privacy.html) is served as itself, not as the game.
    const page = /\\.html$/.test(url.pathname) && SHELL.includes(url.pathname) ? url.pathname : '/index.html';
    event.respondWith(caches.match(page).then((hit) => hit || fetch(req)));
    return;
  }
  event.respondWith(caches.match(req, { ignoreSearch: true }).then((hit) => hit || fetch(req)));
});
`;

/** A hosted build's fetch handler: the paths relative to the worker's folder (`local`). */
const HOSTED_FETCH = `self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  // Only this upload's own files; never the game server, the host's page or another game on the host's origin.
  const path = local(url);
  if (path === null || path === '/sw.js') return;
  if (/^\\/stage\\/[^/]+\\.(mp4|webm)$/.test(path)) {
    event.respondWith(video(req, url));
    return;
  }
  if (/^\\/(music|sfx)\\//.test(path)) {
    event.respondWith(media(req, url));
    return;
  }
  if (onDemand(path)) {
    event.respondWith(sheet(req));
    return;
  }
  // From this upload's cache only (the host's origin holds other games' caches too); the network if not cached yet.
  event.respondWith(
    caches.open(CACHE).then((cache) => {
      if (req.mode === 'navigate') return cache.match(new URL('index.html', self.location.href).href).then((hit) => hit || fetch(req));
      return cache.match(req, { ignoreSearch: true }).then((hit) => hit || fetch(req));
    }),
  );
});
`;
